/* eslint-disable no-invalid-this, no-restricted-syntax */

'use strict';

// MODULES //

var isArrayBuffer = require( '@stdlib/assert/is-arraybuffer' );
var isObject = require( '@stdlib/assert/is-object' );
var hasProp = require( '@stdlib/assert/has-property' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setReadWriteAccessor = require( '@stdlib/utils/define-nonenumerable-read-write-accessor' );
var setReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' );
var propertyDescriptor = require( '@stdlib/utils/property-descriptor' );
var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var join = require( '@stdlib/array/base/join' );
var objectAssign = require( '@stdlib/object/assign' );
var inherit = require( '@stdlib/utils/inherit' );
var resolveMetricStr = require( '@stdlib/ml/base/kmeans/metric-resolve-str' );
var resolveMetricEnum = require( '@stdlib/ml/base/kmeans/metric-resolve-enum' );
var resolveAlgorithmStr = require( '@stdlib/ml/base/kmeans/algorithm-resolve-str' );
var resolveAlgorithmEnum = require( '@stdlib/ml/base/kmeans/algorithm-resolve-enum' );
var structFactory = require( '@stdlib/ml/base/kmeans/results/struct-factory' );
var res2json = require( '@stdlib/ml/base/kmeans/results/to-json' );
var res2str = require( '@stdlib/ml/base/kmeans/results/to-string' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var DTYPES = [
	'float64',
	'float32'
];

var isDataType = contains( DTYPES );


// MAIN //

/**
* Returns a constructor for creating a k-means clustering results object.
*
* @param {string} dtype - storage data type for floating-point values
* @throws {TypeError} first argument must be a supported data type
* @returns {Function} constructor
*
* @example
* var Results = factory( 'float64' );
*
* var results = new Results();
* // returns <Results>
*
* results.replicates = 3;
* results.replicate = 1;
* results.metric = 'sqeuclidean';
* results.iterations = 4;
* results.algorithm = 'lloyd';
* results.inertia = 3.28;
* results.k = 4;
* results.samples = 10;
* results.features = 3;
*
* var str = results.toString();
* // returns <string>
*/
function factory( dtype ) {
	var algorithmDescriptor;
	var metricDescriptor;
	var Struct;

	if ( !isDataType( dtype ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be one of the following: "%s". Value: `%s`.', join( DTYPES, ', ' ), dtype ) );
	}

	// Create a struct constructor:
	Struct = structFactory( dtype );

	// Cache references to property descriptors on the parent prototype so that we can intercept the return values:
	algorithmDescriptor = propertyDescriptor( Struct.prototype, 'algorithm' );
	metricDescriptor = propertyDescriptor( Struct.prototype, 'metric' );

	/**
	* Returns a k-means clustering results object.
	*
	* @private
	* @constructor
	* @param {(ArrayBuffer|Object)} [arg] - underlying byte buffer or a data object
	* @param {NonNegativeInteger} [byteOffset] - byte offset
	* @param {NonNegativeInteger} [byteLength] - maximum byte length
	* @throws {TypeError} first argument must be an ArrayBuffer or a data object
	* @returns {Results} results object
	*/
	function Results( arg, byteOffset, byteLength ) {
		var nargs;
		var args;
		var v;
		var i;

		nargs = arguments.length;
		if ( !( this instanceof Results ) ) {
			if ( nargs === 0 ) {
				return new Results();
			}
			if ( nargs === 1 ) {
				return new Results( arg );
			}
			if ( nargs === 2 ) {
				return new Results( arg, byteOffset );
			}
			return new Results( arg, byteOffset, byteLength );
		}
		args = [];
		if ( nargs > 0 ) {
			if ( isArrayBuffer( arg ) ) {
				for ( i = 0; i < nargs; i++ ) {
					args.push( arguments[ i ] );
				}
			} else if ( isObject( arg ) ) {
				args.push( objectAssign( {}, arg ) );

				// Resolve string-valued enumeration fields to their integer values prior to delegating to the parent constructor...
				if ( hasProp( args[ 0 ], 'algorithm' ) ) {
					v = resolveAlgorithmEnum( args[ 0 ].algorithm );
					args[ 0 ].algorithm = ( v === null ) ? NaN : v;
				}
				if ( hasProp( args[ 0 ], 'metric' ) ) {
					v = resolveMetricEnum( args[ 0 ].metric );
					args[ 0 ].metric = ( v === null ) ? NaN : v;
				}
			} else {
				throw new TypeError( format( 'invalid argument. First argument must be an ArrayBuffer or a data object. Value: `%s`.', arg ) );
			}
		}
		// Call the parent constructor...
		Struct.apply( this, args );
		return this;
	}

	/*
	* Inherit from the parent constructor.
	*/
	inherit( Results, Struct );

	/**
	* Constructor name.
	*
	* @private
	* @name name
	* @memberof Results
	* @readonly
	* @type {string}
	*/
	setReadOnly( Results, 'name', Struct.name );

	/**
	* Alignment.
	*
	* @private
	* @name alignment
	* @memberof Results
	* @readonly
	* @type {PositiveInteger}
	*/
	setReadOnly( Results, 'alignment', Struct.alignment );

	/**
	* Size (in bytes) of the `struct`.
	*
	* @private
	* @name byteLength
	* @memberof Results
	* @readonly
	* @type {PositiveInteger}
	*/
	setReadOnly( Results, 'byteLength', Struct.byteLength );

	/**
	* Returns a list of `struct` fields.
	*
	* @private
	* @name fields
	* @memberof Results
	* @readonly
	* @type {Array<string>}
	*/
	setReadOnlyAccessor( Results, 'fields', function get() {
		return Struct.fields;
	});

	/**
	* Returns a string corresponding to the `struct` layout.
	*
	* @private
	* @name layout
	* @memberof Results
	* @readonly
	* @type {string}
	*/
	setReadOnlyAccessor( Results, 'layout', function get() {
		return Struct.layout;
	});

	/**
	* Returns the underlying byte buffer of a `struct`.
	*
	* @private
	* @name bufferOf
	* @memberof Results
	* @readonly
	* @type {Function}
	* @param {Object} obj - struct instance
	* @throws {TypeError} must provide a `struct` instance
	* @returns {ArrayBuffer} underlying byte buffer
	*/
	setReadOnly( Results, 'bufferOf', Struct.bufferOf );

	/**
	* Returns the length, in bytes, of the value specified by the provided field name.
	*
	* @private
	* @name byteLengthOf
	* @memberof Results
	* @readonly
	* @type {Function}
	* @param {string} name - field name
	* @throws {Error} struct must have at least one field
	* @throws {TypeError} must provide a recognized field name
	* @returns {NonNegativeInteger} byte length
	*/
	setReadOnly( Results, 'byteLengthOf', Struct.byteLengthOf );

	/**
	* Returns the offset, in bytes, from the beginning of a `struct` to the value specified by the provided field name.
	*
	* @private
	* @name byteOffsetOf
	* @memberof Results
	* @readonly
	* @type {Function}
	* @param {string} name - field name
	* @throws {Error} struct must have at least one field
	* @throws {TypeError} must provide a recognized field name
	* @returns {NonNegativeInteger} byte offset
	*/
	setReadOnly( Results, 'byteOffsetOf', Struct.byteOffsetOf );

	/**
	* Returns the description associated with a provided field name.
	*
	* @private
	* @name descriptionOf
	* @memberof Results
	* @readonly
	* @type {Function}
	* @param {string} name - field name
	* @throws {Error} struct must have at least one field
	* @throws {TypeError} must provide a recognized field name
	* @returns {string} description
	*/
	setReadOnly( Results, 'descriptionOf', Struct.descriptionOf );

	/**
	* Returns a boolean indicating whether a provided value is a `struct` instance.
	*
	* @private
	* @name isStruct
	* @memberof Results
	* @readonly
	* @type {Function}
	* @param {*} value - input value
	* @returns {boolean} boolean indicating whether a value is a `struct` instance
	*/
	setReadOnly( Results, 'isStruct', Struct.isStruct );

	/**
	* Returns the type associated with a provided field name.
	*
	* @private
	* @name typeOf
	* @memberof Results
	* @readonly
	* @type {Function}
	* @param {string} name - field name
	* @throws {Error} struct must have at least one field
	* @throws {TypeError} must provide a recognized field name
	* @returns {(string|Object)} type
	*/
	setReadOnly( Results, 'typeOf', Struct.typeOf );

	/**
	* Returns the underlying byte buffer of a `struct` as a `DataView`.
	*
	* @private
	* @name viewOf
	* @memberof Results
	* @readonly
	* @type {Function}
	* @param {Object} obj - struct instance
	* @throws {TypeError} must provide a `struct` instance
	* @returns {DataView} view of underlying byte buffer
	*/
	setReadOnly( Results, 'viewOf', Struct.viewOf );

	/**
	* Analysis name.
	*
	* @private
	* @name method
	* @memberof Results.prototype
	* @type {string}
	* @default 'K-means clustering'
	*/
	setReadOnly( Results.prototype, 'method', 'K-means clustering' );

	/**
	* Distance metric.
	*
	* @private
	* @name metric
	* @memberof Results.prototype
	* @type {string}
	*/
	setReadWriteAccessor( Results.prototype, 'metric', getMetric, setMetric );

	/**
	* Clustering algorithm.
	*
	* @private
	* @name algorithm
	* @memberof Results.prototype
	* @type {string}
	*/
	setReadWriteAccessor( Results.prototype, 'algorithm', getAlgorithm, setAlgorithm );

	/**
	* Serializes a results object as a string.
	*
	* ## Notes
	*
	* -   Example output:
	*
	*     ```text
	*
	*     K-means clustering using Lloyd algorithm
	*
	*         metric used: squared euclidean
	*         total replicates: 4
	*         best replicate: 2
	*         total iterations: 10
	*         inertia: 3.2800
	*
	*     Clustering ran for 4 clusters and 10 data samples, each with 3 features
	*
	*     ```
	*
	* @private
	* @name toString
	* @memberof Results.prototype
	* @type {Function}
	* @param {Options} [opts] - options object
	* @param {PositiveInteger} [opts.digits=4] - number of digits after the decimal point
	* @throws {TypeError} options argument must be an object
	* @throws {TypeError} must provide valid options
	* @returns {string} serialized results
	*/
	setReadOnly( Results.prototype, 'toString', function toString( opts ) {
		if ( arguments.length ) {
			return res2str( this, opts );
		}
		return res2str( this );
	});

	/**
	* Serializes a results object as a JSON object.
	*
	* ## Notes
	*
	* -   `JSON.stringify()` implicitly calls this method when stringifying a `Results` instance.
	*
	* @private
	* @name toJSON
	* @memberof Results.prototype
	* @type {Function}
	* @returns {Object} serialized object
	*/
	setReadOnly( Results.prototype, 'toJSON', function toJSON() {
		return res2json( this );
	});

	/**
	* Returns a DataView of a results object.
	*
	* @private
	* @name toDataView
	* @memberof Results.prototype
	* @type {Function}
	* @returns {DataView} DataView
	*/
	setReadOnly( Results.prototype, 'toDataView', function toDataView() {
		return Struct.viewOf( this );
	});

	return Results;

	/**
	* Returns the distance metric.
	*
	* @private
	* @returns {string} distance metric
	*/
	function getMetric() {
		return resolveMetricStr( metricDescriptor.get.call( this ) );
	}

	/**
	* Sets the distance metric.
	*
	* @private
	* @param {string} value - distance metric
	*/
	function setMetric( value ) {
		metricDescriptor.set.call( this, resolveMetricEnum( value ) );
	}

	/**
	* Returns the clustering algorithm.
	*
	* @private
	* @returns {string} clustering algorithm
	*/
	function getAlgorithm() {
		return resolveAlgorithmStr( algorithmDescriptor.get.call( this ) );
	}

	/**
	* Sets the clustering algorithm.
	*
	* @private
	* @param {string} value - clustering algorithm
	*/
	function setAlgorithm( value ) {
		algorithmDescriptor.set.call( this, resolveAlgorithmEnum( value ) );
	}
}


// EXPORTS //

module.exports = factory;
